<div class="page-head"><div><span class="eyebrow">ACADÉMICO · OFERTA</span><h1><?=htmlspecialchars($offer['nombre'])?></h1><p><?=htmlspecialchars($offer['periodo'])?> · <?=htmlspecialchars($offer['carrera'])?> · <?=htmlspecialchars($offer['malla'])?></p></div><div><a href="<?=$u?>/admin/academico/oferta">Volver</a><?php if($manage):?> · <a href="<?=$u?>/admin/academico/oferta/form?id=<?=$offer['id']?>">Editar oferta</a><?php endif;?></div></div>
